&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 2&quot;&gt;To Apply&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;As part of your application, please include your resume and a thoughtful cover letter, addressed&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;to&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Michelle Carson&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;outli&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;ning&lt;/span&gt;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;&amp;nbsp;how your skills and experience meet the qualifications of the position.&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:288}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
